import {HUD_WIDGETS,HUD_SCALE,getHudLayoutPreferences,normalizeHudLayout} from './hud-layout.js';
import {createHudEditorPreview} from './hud-editor-preview.js';
const clone=value=>structuredClone(value),clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
export async function openHudEditor({document:doc,preferences=getHudLayoutPreferences(),onApply=()=>{},onClose=()=>{}}={}){
 const prior=doc.querySelector('[data-hud-editor]');if(prior)throw Error('editor-open');
 const dialog=doc.createElement('dialog');dialog.dataset.hudEditor='';dialog.className='hud-editor';dialog.setAttribute('aria-label','Organizar interface');
 dialog.innerHTML=`<header class="he-head"><div><h2>Organizar UI</h2><small>Prévia · valores de exemplo</small></div><button type="button" data-action="panel">Painel</button><button type="button" class="he-close" data-action="cancel" aria-label="Fechar editor">×</button></header><div class="he-toolbar"><label>Cenário <select data-field="scene"><option value="cave">Caverna</option><option value="boss">Boss</option><option value="abyss">Abismo</option></select></label><label><input type="checkbox" data-field="grid" checked> Grade</label><label><input type="checkbox" data-field="guides" checked> Guias</label><button type="button" data-action="undo" aria-label="Desfazer">↶</button><button type="button" data-action="redo" aria-label="Refazer">↷</button></div><div class="he-work"><section class="he-canvas" aria-label="Prévia da organização"></section><aside class="he-inspector"><label>Bloco<select data-field="widget">${HUD_WIDGETS.map(w=>'<option value="'+w.id+'">'+w.name+'</option>').join('')}</select></label><div class="he-fields"><label>X <input type="number" min="0" max="100" step="1" data-field="x"><span>%</span></label><label>Y <input type="number" min="0" max="100" step="1" data-field="y"><span>%</span></label></div><label class="he-size"><span>Tamanho <output data-field="scaleValue">100%</output></span><input type="range" min="65" max="175" step="5" value="100" data-field="scale" aria-label="Tamanho do bloco"></label><label class="he-visible"><input type="checkbox" data-field="visible" checked> Visível</label><button type="button" data-action="reset-widget">Padrão do bloco</button><details><summary>Presets</summary><label>Preset<select data-field="preset"></select></label><div class="he-preset-actions"><button type="button" data-action="new">+ Novo</button><button type="button" data-action="copy">Duplicar</button><button type="button" data-action="delete">Excluir</button></div><label class="he-name">Nome<input data-field="name" maxlength="32" value="Meu HUD" placeholder="Nome do preset"></label><button type="button" data-action="save">Salvar preset</button></details><small class="he-keys">Setas movem · Shift acelera</small></aside></div><footer class="he-footer"><span role="status" data-field="status"></span><button type="button" data-action="cancel">Cancelar</button><button type="button" data-action="reset">Restaurar padrão</button><button type="button" class="primary" data-action="apply">Aplicar</button></footer>`;
 doc.body.append(dialog);dialog.showModal();const $=s=>dialog.querySelector(s),field=id=>$('[data-field='+id+']'),action=id=>$('[data-action='+id+']');
 let draft=clone(preferences.getState().current),selected='life',presetId='__current',closed=false,preview=null,drag=null;const undo=[],redo=[];
 const stage=doc.getElementById('world'),rect=stage?.getBoundingClientRect();const width=Math.max(640,Math.round(rect?.width||doc.defaultView.innerWidth)),height=Math.max(480,Math.round(rect?.height||doc.defaultView.innerHeight));
 let background=null;
 const uiScale=Number(doc.documentElement.style.getPropertyValue('--gv-ui-scale'))||1;
 function status(text){field('status').textContent=text;}
 function history(before){undo.push(clone(before));if(undo.length>40)undo.shift();redo.length=0;}
 function update(){if(!preview)return;draft=normalizeHudLayout(draft);preview.setLayout(draft);preview.select(selected);field('widget').value=selected;const entry=draft[selected]||{},r=preview.rect(selected);field('x').value=Math.round((entry.x??r?.x??.5)*100);field('y').value=Math.round((entry.y??r?.y??.5)*100);field('scale').value=Math.round((entry.scale||1)*100);field('scaleValue').textContent=field('scale').value+'%';field('visible').checked=!entry.hidden;action('undo').disabled=!undo.length;action('redo').disabled=!redo.length;}
 function mutate(fn){history(draft);fn();update();status('');}
 function select(id){selected=id;preview?.select(id);field('scene').value=id==='boss'?'boss':id==='sentinel'?'cave':field('scene').value;update();}
 function entry(){return draft[selected]??(draft[selected]={scale:1,hidden:false});}
 function presetOptions(){const state=preferences.getState(),select=field('preset');select.replaceChildren();for(const [id,name]of [['__current','Em uso'],['__default','Padrão'],...state.presets.map(p=>[p.id,p.name])]){const option=doc.createElement('option');option.value=id;option.textContent=name;select.append(option);}select.value=presetId;action('delete').disabled=!state.presets.some(p=>p.id===presetId);}
 function save(copy=false){const result=preferences.savePreset(field('name').value,draft,copy?null:presetId);if(!result.ok){status(result.reason==='limit'?'Até 8 presets.':'Dê um nome ao preset.');field('name').focus();return;}presetId=result.id;presetOptions();status(result.persisted?'Preset salvo.':'Preset ativo nesta sessão.');}
 function close(reason='cancel'){if(closed)return;closed=true;preview?.dispose();if(dialog.open)dialog.close();dialog.remove();onClose(reason);if(reason==='apply')onApply();}
 function dragStart(event,id,resize){
  if(event.type==='keydown'){
   if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();event.stopPropagation();select(id);const r=preview.rect(id),step=(event.shiftKey?10:1);if(!r)return;mutate(()=>{const e=entry();e.x=clamp((e.x??r.x)+({'ArrowLeft':-step,'ArrowRight':step}[event.key]||0)/preview.root.clientWidth,0,1);e.y=clamp((e.y??r.y)+({'ArrowUp':-step,'ArrowDown':step}[event.key]||0)/preview.root.clientHeight,0,1);});return;
  }
  if(event.button!==0)return;event.preventDefault();event.stopPropagation();select(id);const r=preview.rect(id);if(!r)return;
  drag={id,resize,original:clone(draft),x:event.clientX,y:event.clientY,rect:r,scale:draft[id]?.scale||1,target:event.currentTarget};drag.target.setPointerCapture(event.pointerId);
 }
 function dragMove(event){if(!drag)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)<3)return;selected=drag.id;const e=entry();
  if(drag.resize){e.x=e.x??drag.rect.x;e.y=e.y??drag.rect.y;let n=drag.scale*(1+(dx+dy)/Math.max(1,drag.rect.width+drag.rect.height));e.scale=Math.round(clamp(n,HUD_SCALE.min,HUD_SCALE.max)*20)/20;}
  else{let x=drag.rect.x+dx/drag.rect.root.width,y=drag.rect.y+dy/drag.rect.root.height;if(field('grid').checked){const w=preview.root.clientWidth,h=preview.root.clientHeight;x=Math.round(x*w/8)*8/w;y=Math.round(y*h/8)*8/h;}e.x=clamp(x,0,1);e.y=clamp(y,0,1);}
  update();
 }
 function dragEnd(){if(!drag)return;if(JSON.stringify(draft)!==JSON.stringify(drag.original))history(drag.original);drag=null;update();}
 dialog.addEventListener('pointermove',dragMove);dialog.addEventListener('pointerup',dragEnd);dialog.addEventListener('pointercancel',dragEnd);
 dialog.addEventListener('cancel',event=>{event.preventDefault();close();});dialog.addEventListener('keydown',event=>{event.stopPropagation();if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();action(event.shiftKey?'redo':'undo').click();}});
 for(const button of dialog.querySelectorAll('[data-action=cancel]'))button.onclick=()=>close();
 action('panel').onclick=()=>dialog.classList.toggle('panel-hidden');action('reset').onclick=()=>mutate(()=>draft={});action('reset-widget').onclick=()=>mutate(()=>delete draft[selected]);
 action('undo').onclick=()=>{if(!undo.length)return;redo.push(clone(draft));draft=undo.pop();update();};action('redo').onclick=()=>{if(!redo.length)return;undo.push(clone(draft));draft=redo.pop();update();};
 action('apply').onclick=()=>{preferences.apply(draft);close('apply');};
 action('save').onclick=()=>save();action('copy').onclick=()=>{field('name').value=(field('name').value+' cópia').slice(0,32);save(true);};action('new').onclick=()=>{presetId='__current';field('name').value='';presetOptions();field('name').focus();};
 action('delete').onclick=()=>{if(preferences.deletePreset(presetId)){presetId='__current';presetOptions();status('Preset excluído.');}};
 field('preset').onchange=()=>{presetId=field('preset').value;const value=preferences.getState().presets.find(p=>p.id===presetId);mutate(()=>draft=clone(presetId==='__default'?{}:value?.widgets||preferences.getState().current));field('name').value=value?.name||'Meu HUD';presetOptions();};
 field('widget').onchange=()=>select(field('widget').value);field('scene').onchange=()=>{preview.setScene(field('scene').value);update();};field('grid').onchange=()=>preview.setGrid(field('grid').checked);field('guides').onchange=()=>preview.setGuides(field('guides').checked);
 for(const name of ['x','y'])field(name).onchange=()=>{const n=Number(field(name).value);if(!Number.isFinite(n))return;mutate(()=>{const e=entry(),r=preview.rect(selected);e.x=e.x??r?.x??.5;e.y=e.y??r?.y??.5;e[name]=clamp(n/100,0,1);});};
 field('scale').oninput=()=>mutate(()=>{const e=entry(),r=preview.rect(selected);e.x=e.x??r?.x??.5;e.y=e.y??r?.y??.5;e.scale=Number(field('scale').value)/100;});field('visible').onchange=()=>mutate(()=>entry().hidden=!field('visible').checked);
 for(const n of dialog.querySelectorAll('button,input,select'))if(n.dataset.action!=='cancel')n.disabled=true;
 presetOptions();try{ try{stage?.dispatchEvent(new doc.defaultView.Event('gemventure-preview-capture'));if(stage?.dataset.gvSceneReady==='false'){const limit=performance.now()+5000;while(stage.dataset.gvSceneReady==='false'&&performance.now()<limit&&!closed){stage.dispatchEvent(new doc.defaultView.Event('gemventure-preview-capture'));if(stage.dataset.gvSceneReady!=='false')break;await new Promise(resolve=>doc.defaultView.requestAnimationFrame(resolve));}}background=stage?.toDataURL('image/jpeg',.85);}catch{}if(closed)return {close};preview=await createHudEditorPreview($('.he-canvas'),{document:doc,background,width,height,uiScale,onSelect:select,onDrag:dragStart});if(closed){preview.dispose();return {close};}for(const n of dialog.querySelectorAll('button,input,select'))n.disabled=false;presetOptions();update();action('apply').focus();}catch{status('Não foi possível carregar a prévia.');action('apply').disabled=true;}
 return {close:()=>close(),getDraft:()=>clone(draft)};
}
